import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.CqGS6Fr9.js";const h=JSON.parse('{"title":"Building the project","description":"","frontmatter":{"pageId":"developers/build","contentRevision":1},"headers":[],"relativePath":"en/developers/build.md","filePath":"en/developers/build.md"}'),n={name:"en/developers/build.md"};function s(r,e,l,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="building-the-project" tabindex="-1">Building the project <a class="header-anchor" href="#building-the-project" aria-label="Permalink to &quot;Building the project&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>Install the SDK pinned in global.json; package versions are centralized in Directory.Packages.props. From the repository root run:</p><p><code>dotnet build Rimlink.sln</code></p><p><code>dotnet test Rimlink.sln -nologo -v q</code></p><p>The mod is outside the solution: close the game and use PowerShell scripts/Build-ClientMod.ps1 -RimWorldDir &lt;game&gt; -InstallTo &lt;game/Mods&gt;. -BundleHarmony is only for local runs without separate Harmony, never releases. scripts/Package-Release.ps1 produces release ZIPs.</p><p>For the wiki: npm --prefix wiki ci --ignore-scripts, then run test:checks, check:content, check:reference, build and check:links. Node 24 is pinned separately. BridgeTools requires its separate Build-BridgeTools.ps1 and an installed game.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Do not replace a running game&#39;s DLLs or restart someone else&#39;s instance. A solution build proves neither mod compilation nor gameplay. Keep bin/obj/data/saves/secrets and generated wiki output out of commits.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./testing">Testing and acceptance</a></li><li><a href="./contributing">Contributing and wiki maintenance</a></li><li><a href="./../admins/hosting">Hosting and startup</a></li></ul>',12)])])}const m=a(n,[["render",s]]);export{h as __pageData,m as default};
